// One event, one journalist, one send — a press pitch is a
// first approach to somebody else's relationship, never a blast.
const e = $json;
if (!e || e.type !== 'crowdrelay.agent.content_requested' || e.version !== 1) return [];
const d = e.data ?? {};
if (d.template_id !== 'press-pitch') return [];
if (!d.action_id || !d.recipient_email) return [];
// The dispatch gate's half of the contract rides on the event: a send
// without send_evidence means the gate was bypassed upstream, and this
// executor refuses rather than mailing on a payload nobody evidenced.
if (!d.send_evidence || !d.send_evidence.source_id || !d.send_evidence.recipient_reason) {
  throw new Error('press pitch refused: send_evidence missing — dispatch gate bypassed');
}
const draft = d.draft ?? {};
const subject = String(draft.subject ?? '').trim();
const body = String(draft.body ?? draft.draft_text ?? '').trim();
if (!subject || !body) throw new Error('press pitch draft has no subject/body');
const replyTo = $env.VIRYA_PRESS_REPLY_TO || $env.VIRYA_OUTREACH_FROM_EMAIL;
if (!replyTo) throw new Error('Missing monitored reply-to configuration');
return [{ json: {
  event_id: e.id,
  action_id: String(d.action_id),
  recipient_email: String(d.recipient_email),
  recipient_name: d.recipient_name ?? null,
  recipient_target_id: d.recipient_target_id ?? null,
  subject,
  body,
  reply_to: replyTo,
  send_evidence: d.send_evidence,
}}];

const claim = $json;
const intent = $('Validate and prepare pitch').first().json;
if (claim.disposition !== 'claimed') return [];
if (!claim.claim_token) throw new Error('Missing claim token');
return [{ json: { ...intent, claim_token: claim.claim_token } }];

const intent = $('Fail-closed claim gate').first().json;
const failed = Boolean($json.error);
const ref = $json.threadId || $json.thread_id || $json.id || null;
return [{ json: {
  action_id: intent.action_id,
  receipt_key: `press_pitch:${intent.action_id}:email`,
  executor_id: $env.VIRYA_N8N_EXECUTOR_ID,
  status: failed ? 'failed' : 'succeeded',
  claim_token: intent.claim_token,
  provider_reference: failed ? null : (ref ? String(ref) : null),
  error_kind: failed ? 'gmail_send_failed' : null,
  metadata: {
    channel: 'email',
    recipient_target_id: intent.recipient_target_id,
    send_evidence: intent.send_evidence,
  },
  occurred_at: new Date().toISOString(),
}}];
